function slugToTitle(slug) {
  return slug.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
}

function getNavActive(category) {
  const map = { dogs: 'Dogs', cats: 'Cats', birds: 'Birds', fish: 'Fish', reptiles: 'Reptiles', 'small-animals': 'Dogs' };
  return map[category] || '';
}

function getCategoryLabel(category) {
  const map = { dogs: 'Dogs', cats: 'Cats', birds: 'Birds', fish: 'Fish & Aquarium', reptiles: 'Reptiles', 'small-animals': 'Small Animals' };
  return map[category] || category;
}

function getCategoryUrl(category) {
  const map = { dogs: '/dogs', cats: '/cats', birds: '/birds', fish: '/fish', reptiles: '/reptiles', 'small-animals': '/small-animals' };
  return map[category] || '/';
}

function getBreedsUrl(category) {
  const map = { dogs: '/breeds/dog-breeds', cats: '/breeds/cat-breeds', birds: '/breeds/bird-breeds', fish: '/breeds/fish-breeds', reptiles: '/breeds/reptile-breeds', 'small-animals': '/breeds/small-animal-breeds' };
  return map[category] || '/breeds';
}

