// MAIN EXECUTION
// ============================================================

const counts = {};
let totalGenerated = 0;

for (const [category, speciesList] of Object.entries(SPECIES)) {
  counts[category] = 0;
  const dir = join(ROOT, 'breeds', category);
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });

  for (const species of speciesList) {
    const filePath = join(dir, `${species.slug}.html`);
    if (existsSync(filePath)) {
      continue; // Don't overwrite existing pages
    }

    let html;
    if (category === 'dogs') {
      html = generateDogPage(species);
    } else {
      html = generateGenericPage(category, species);
    }

    writeFileSync(filePath, html, 'utf-8');
    counts[category]++;
    totalGenerated++;
  }
}

console.log('Species Expansion Complete!');
console.log('Pages generated per category:');
for (const [cat, count] of Object.entries(counts)) {
  console.log(`  ${cat}: ${count} new pages`);
}
console.log(`Total new pages: ${totalGenerated}`);
